    const pts = items.map((p, i) => `${xAt(i).toFixed(1)},${yAt(Number(getKey(p))).toFixed(1)}`).join(' ');
    out += `<polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>`;
