      out += `<circle cx="${xAt(i).toFixed(1)}" cy="${yAt(v).toFixed(1)}" r="4" fill="${color}">
        <title>${esc(p.label)} — ${name}: ${fmtShort(v)}</title>
      </circle>`;
    });
  };

  if (twoLines) {
    drawSeries(p => p.a, '#2f5d50', 'Series A');
    drawSeries(p => p.b, '#c96f4a', 'Series B');
    // legend
    out += `<g font-size="11" fill="${TEXT}">
