      <text x="${pad.left + 104}" y="13">${esc(options.labelB || 'Series B')}</text>
    </g>`;
  } else {
    drawSeries(p => p.value, '#2f5d50', options.seriesName || 'Value');
  }

  out += `</svg>`;
