    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function buildMonths() {
  const months = [];
  let m = currentMonthKey();
  for (let i = 0; i < 6; i++) {
    months.unshift(m);
    m = prevMonth(m);
  }
  return months;
}

function insightCard(title, body) {
  return `<div class="insight-card"><h4>${esc(title)}</h4><p>${body}</p></div>`;
