  let moM = null;
  parts.forEach(p => {
    const delta = p.value - (prevTotals[p.label] || 0);
    if (!moM || delta > moM.delta) moM = { label: p.label, delta, prev: prevTotals[p.label] || 0 };
  });
  const momCard = moM
